    #[error("sha256 mismatch: {0}")]
    HashMismatch(String),
}

//! Data-driven model catalog.
//!
//! The speech, LLM, and command catalogs are JSON files parsed at runtime,
//! owned by this crate. The Rust side keeps the schema, the engine registry,
//! the validator, and the loader; adding a model is a data edit.

pub mod engine;
pub mod loader;
pub mod schema;
pub mod validate;

pub use engine::Engine;
pub use schema::{Artifact, Capability, Catalog, CommandEntry, LlmEntry, Purpose, SpeechEntry};
pub use validate::{validate_catalog, validate_command, validate_llm, validate_speech};

/// Errors the catalog can surface.
#[derive(Debug, thiserror::Error)]
pub enum CatalogError {
    #[error("unknown engine name: {0}")]
    UnknownEngine(String),
    #[error("invalid JSON: {0}")]
    InvalidJson(String),
    #[error("catalog validation failed: {0}")]
    Validation(String),
    #[error("I/O error: {0}")]
    Io(#[from] std::io::Error),
    #[error("network error: {0}")]
    Network(String),
    #[error("sha256 mismatch: {0}")]
    HashMismatch(String),
}

//! Entry schema for the data-driven model catalog.
//!
//! The schema is the union of the old `SpeechModel` and `CatalogEntry`
//! structs plus the capability set, field for field so nothing is lost in
//! the migration to JSON.

use serde::{Deserialize, Serialize};

/// The user-facing capability set a model declares.
///
/// `asr` transcribes voice to text, `polish` cleans up transcribed text,
/// `tool_calling` can emit structured tool calls (command mode), and `omni`
/// marks a one-model-does-everything model that runs its own pipeline.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Capability {
    Asr,
    Polish,
    ToolCalling,
    Omni,
}

/// One file of a model artifact, with the exact published bytes and the
/// publisher's SHA-256.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Artifact {
    pub file: String,
    pub bytes: u64,
    pub sha256: Option<String>,
}

/// Why a speech row is worth choosing, shown as a chip beside the name.
/// `measured` separates a role this repo has measured from one inferred
/// from the model card or engine.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Purpose {
    pub label: String,
    pub basis: String,
    /// Eval file or report that proves a measured chip, relative to the repo
    /// root. Required when `basis` is `measured`; `null` for `inferred`.
    pub evidence: Option<String>,
}

/// One ASR (dictation) model.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct SpeechEntry {
    pub id: String,
    pub name: String,
    /// Engine registry name (see `teletype_catalog::engine::Engine`).
    pub engine: String,
    pub capabilities: Vec<Capability>,
    /// Languages the model can transcribe, or `null` for every engine
    /// language (Whisper's 99).
    pub languages: Option<Vec<String>>,
    pub english_only: bool,
    /// The model's files. Single-file, two-file (llama-server pair), and
    /// shard shapes all collapse into this list. Empty for the Core ML
    /// repo shape and the OS-managed Apple-speech shape.
    pub artifacts: Vec<Artifact>,
    /// Optional download base URL override. `null` means the engine's
    /// default base URL is used.
    pub base_url: Option<String>,
    /// Approximate download size in decimal MB.
    pub size_mb: u32,
    pub min_ram_gb: u32,
    pub speed: f64,
    pub accuracy: f64,
    pub recommended: bool,
    /// Companion model, not a dictation engine.
    pub auxiliary: bool,
    /// Platform set the row is offered on: `macos`, `windows`, `linux`.
    pub runs_on: Vec<String>,
    pub purposes: Vec<Purpose>,
    pub description: String,
}

/// One polish/LLM model.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct LlmEntry {
    pub id: String,
    pub name: String,
    /// Approximate parameter class, for display.
    pub size_label: String,
    /// Replaces the old `polish_capable` bool; a polish row carries
    /// `["polish"]`.
    pub capabilities: Vec<Capability>,
    pub url: String,
    /// Approximate download size in decimal MB.
    pub size_mb: u32,
    pub description: String,
    /// What this row is worth choosing for, shown as a chip beside the name.
    pub specialty: String,
    pub sha256: Option<String>,
    pub backup_url: Option<String>,
    pub attribution: Option<String>,
    pub license_name: Option<String>,
    pub license_url: Option<String>,
    pub requires_license_accept: bool,
    pub recommended: bool,
    pub runs_on_cpu: bool,
    pub verdict: String,
    pub verdict_note: String,
    pub sort_order: u32,
    /// Non-empty for multi-file (split) GGUFs.
    pub shards: Vec<Artifact>,
    /// Platform set the row is offered on: `macos`, `windows`, `linux`.
    pub runs_on: Vec<String>,
}

/// One command-mode decider model.
///
/// Carries the FULL display field set the UI reads for the decider row (R3),
/// in addition to the base fields.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct CommandEntry {
    pub id: String,
    pub name: String,
    /// Engine registry name (the decider is `onnx`).
    pub engine: String,
    /// Always includes `tool_calling`.
    pub capabilities: Vec<Capability>,
    pub artifacts: Vec<Artifact>,
    pub base_url: Option<String>,
    pub size_mb: u32,
    pub description: String,
    pub runs_on: Vec<String>,
    pub runs_on_cpu: bool,
    pub size_label: String,
    pub specialty: String,
    pub sha256: Option<String>,
    pub backup_url: Option<String>,
    pub attribution: Option<String>,
    pub license_name: Option<String>,
    pub license_url: Option<String>,
    pub requires_license_accept: bool,
    pub recommended: bool,
    pub verdict: String,
    pub verdict_note: String,
    pub sort_order: u32,
    pub shards: Vec<Artifact>,
}

/// The three pipeline domains, parsed from the three JSON files.
#[derive(Debug, Clone, PartialEq, Default)]
pub struct Catalog {
    pub speech: Vec<SpeechEntry>,
    pub llm: Vec<LlmEntry>,
    pub command: Vec<CommandEntry>,
}

//! Data-driven model catalog.
//!
//! The speech, LLM, and command catalogs are JSON files parsed at runtime,
//! owned by this crate. The Rust side keeps the schema, the engine registry,
//! the validator, and the loader; adding a model is a data edit.

pub mod engine;
pub mod loader;
pub mod schema;
pub mod validate;

pub use engine::Engine;
pub use schema::{Artifact, Capability, Catalog, CommandEntry, LlmEntry, Purpose, SpeechEntry};
pub use validate::{validate_catalog, validate_command, validate_llm, validate_speech};

/// Errors the catalog can surface.
#[derive(Debug, thiserror::Error)]
pub enum CatalogError {
    #[error("unknown engine name: {0}")]
    UnknownEngine(String),
    #[error("invalid JSON: {0}")]
    InvalidJson(String),
    #[error("catalog validation failed: {0}")]
    Validation(String),
    #[error("I/O error: {0}")]
    Io(#[from] std::io::Error),
    #[error("network error: {0}")]
    Network(String),
    #[error("sha256 mismatch: {0}")]
    HashMismatch(String),
}

//! Engine registry: the existing `Engine` enum re-keyed by a stable string
//! name, plus `Onnx` for the NeuDecide command decider.
//!
//! `Platform` is DEFINED here so the catalog crate has no speech dependency;
//! `teletype-speech` re-exports it.

use crate::CatalogError;

/// The host platform facts the engine predicates need.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Platform {
    /// macOS on Apple Silicon; `major` is the macOS major version (14+ gets
    /// the Neural Engine engines).
    MacosAppleSilicon { major: u16 },
    /// macOS on Intel - no Neural Engine, so the ggml build is the default.
    MacosIntel,
    /// Windows - sherpa-onnx is the default engine.
    Windows,
    /// Anything else (Linux, ...) - the ggml build is the default.
    Other,
}

impl Platform {
    /// macOS of either architecture.
    pub fn is_macos(self) -> bool {
        matches!(
            self,
            Platform::MacosAppleSilicon { .. } | Platform::MacosIntel
        )
    }
}

/// Which local engine loads a model.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Engine {
    Whisper,
    Parakeet,
    ParakeetCoreml,
    SherpaParakeet,
    ParakeetCpp,
    Qwen3Asr,
    AppleSpeech,
    TranscribeCpp,
    /// The NeuDecide command decider; no speech provider, never offered as a
    /// speech row.
    Onnx,
}

impl Engine {
    /// Resolve a registry name to its engine. Unknown names are an error,
    /// never a variant (closed-engine-set guarantee).
    pub fn from_name(name: &str) -> Result<Engine, CatalogError> {
        match name {
            "whisper" => Ok(Engine::Whisper),
            "parakeet" => Ok(Engine::Parakeet),
            "parakeet-coreml" => Ok(Engine::ParakeetCoreml),
            "sherpa" => Ok(Engine::SherpaParakeet),
            "parakeet-cpp" => Ok(Engine::ParakeetCpp),
            "llama-server" => Ok(Engine::Qwen3Asr),
            "apple-speech" => Ok(Engine::AppleSpeech),
            "transcribe-cpp" => Ok(Engine::TranscribeCpp),
            "onnx" => Ok(Engine::Onnx),
            other => Err(CatalogError::UnknownEngine(other.to_string())),
        }
    }

    /// The stable registry name for this engine.
    pub fn name(self) -> &'static str {
        match self {
            Engine::Whisper => "whisper",
            Engine::Parakeet => "parakeet",
            Engine::ParakeetCoreml => "parakeet-coreml",
            Engine::SherpaParakeet => "sherpa",
            Engine::ParakeetCpp => "parakeet-cpp",
            Engine::Qwen3Asr => "llama-server",
            Engine::AppleSpeech => "apple-speech",
            Engine::TranscribeCpp => "transcribe-cpp",
            Engine::Onnx => "onnx",
        }
    }

    /// Whether this engine ships on `platform`.
    pub fn available_on(self, platform: Platform) -> bool {
        match self {
            Engine::Whisper | Engine::Parakeet | Engine::ParakeetCpp => platform.is_macos(),
            Engine::ParakeetCoreml => {
                matches!(platform, Platform::MacosAppleSilicon { major } if major >= 14)
            }
            Engine::SherpaParakeet => true,
            Engine::AppleSpeech => {
                matches!(platform, Platform::MacosAppleSilicon { major } if major >= 26)
            }
            Engine::Qwen3Asr => platform.is_macos(),
            Engine::TranscribeCpp => platform.is_macos(),
            Engine::Onnx => true,
        }
    }

    /// Whether this build actually compiled the engine, given the host's
    /// engine-capability facts.
    ///
    /// The catalog crate has no speech dependency, so the two build facts
    /// (parakeet.cpp and transcribe.cpp availability) are passed in by the
    /// caller that owns those engine modules.
    pub fn built_on(
        self,
        platform: Platform,
        parakeet_cpp_available: bool,
        transcribe_cpp_available: bool,
    ) -> bool {
        match self {
            Engine::ParakeetCpp => platform.is_macos() && parakeet_cpp_available,
            Engine::TranscribeCpp => platform.is_macos() && transcribe_cpp_available,
            _ => true,
        }
    }

    /// Short display name for the engine, shown by the model list UI.
    pub fn label(self) -> &'static str {
        match self {
            Engine::Whisper => "whisper.cpp",
            Engine::Parakeet => "parakeet (ggml)",
            Engine::ParakeetCoreml => "Neural Engine (Core ML)",
            Engine::SherpaParakeet => "sherpa-onnx (CPU)",
            Engine::ParakeetCpp => "parakeet.cpp",
            Engine::Qwen3Asr => "Qwen3-ASR (llama.cpp)",
            Engine::AppleSpeech => "Apple speech (on-device)",
            Engine::TranscribeCpp => "transcribe.cpp",
            Engine::Onnx => "ONNX decider",
        }
    }

    /// Human-readable platform requirement, shown next to the engine label.
    pub fn platform_label(self) -> &'static str {
        match self {
            Engine::Whisper | Engine::Parakeet | Engine::ParakeetCpp => "macOS only",
            Engine::ParakeetCoreml => "Apple Silicon, macOS 14+",
            Engine::SherpaParakeet => "Windows, macOS, Linux",
            Engine::Qwen3Asr => "macOS only (llama-server)",
            Engine::AppleSpeech => "Apple Silicon, macOS 26+",
            Engine::TranscribeCpp => "macOS only (transcribe.cpp)",
            Engine::Onnx => "any",
        }
    }
}

