    "ko", "ms", "nl", "no", "pl", "pt", "ro", "ru", "sk", "sv", "tr", "uk", "vi", "zh",
];

/// The 19 transcription-ready locales of Nemotron 3.5 ASR streaming 0.6B
/// (model card tier table, read 2026-11-01; the broad-coverage 13 and the
