/// One file of a multi-file model artifact, with the exact published bytes
/// and the publisher's SHA-256.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct SpeechArtifact {
    pub file: &'static str,
    pub bytes: u64,
