    "English only",
    "Live streaming",
    "Context-aware",
    "Low memory",
    "No download",
    "Long recordings",
    "Indian languages",
    "Experimental",
];

impl Purpose {
    const fn measured(label: &'static str, evidence: &'static str) -> Self {
        Self {
            label,
            basis: PurposeBasis::Measured,
            evidence: Some(evidence),
        }
    }

    const fn inferred(label: &'static str) -> Self {
        Self {
            label,
            basis: PurposeBasis::Inferred,
            evidence: None,
        }
    }
}

