        assert!(moonshine.english_only, "moonshine is English-only");
        assert!(!moonshine.honours_language(Some("de")));
        let granite = find("granite-speech-470m-q4").unwrap();
        let granite_langs: &[&str] = &["en", "fr", "de", "es", "pt", "it", "ja"];
        assert_eq!(
