    const PLATFORMS: &[Platform] = &[
        Platform::MacosAppleSilicon { major: 26 },
        Platform::MacosAppleSilicon { major: 15 },
        Platform::MacosAppleSilicon { major: 14 },
        Platform::MacosAppleSilicon { major: 13 },
        Platform::MacosIntel,
        Platform::Windows,
        Platform::Other,
    ];
    const LANGUAGES: &[Option<&str>] = &[
        None,
