        // never under-report the two files it stands for.
        let total_mb = (arts.iter().map(|a| a.bytes).sum::<u64>() / 1_048_576) as u32;
        assert!(
            (total_mb..=(total_mb as usize * 120 / 100) as u32).contains(&m.size_mb),
            "size_mb {} vs {} bytes of artifacts",
            m.size_mb,
            total_mb
        );
