    fn qwen3_asr_row_is_well_formed() {
        let m = find("qwen3-asr").expect("qwen3-asr entry");
        assert_eq!(m.engine, Engine::Qwen3Asr);
        // macOS only, and only where llama-server was built with the mtmd
