/// Whether the FluidAudio bridge is compiled into this build (macOS 14+
/// Apple Silicon without `TELETYPE_FLUID_DISABLE_SWIFT=1`).
pub fn fluid_bridge_available() -> bool {
    teletype_fluid::bridge_built()
}

/// Whether the Apple speech bridge is compiled into this build (macOS
/// Apple Silicon without `TELETYPE_APPLE_DISABLE_SWIFT=1`).
pub fn apple_bridge_available() -> bool {
    teletype_apple::bridge_built()
}

/// The model path a measure run loads for `model`, under `models_dir`.
///
/// Delegates to the catalog's per-engine layout so the harness and the app
/// cannot drift: Fluid → `<models_dir>/fluid` (the provider appends the repo
/// folder and downloads on first load), sherpa → the extracted directory
/// `<models_dir>/sherpa/<archive stem>` (which must contain the ONNX files),
/// ggml → `<models_dir>/<file>`.
pub fn model_path_for(models_dir: &Path, model: &teletype_speech::catalog::SpeechModel) -> PathBuf {
    model.provider_path(models_dir)
}

/// Whether the model files for `model` are present under `models_dir`.
///
/// ggml: the single `.bin` exists. sherpa: the extracted directory carries
/// all four ONNX/token files. Qwen3-ASR: both GGUFs of the pair exist. Fluid:
/// the bridge is compiled in (the
/// checkpoint itself is downloaded by the provider on first load, so
/// presence = the bridge can run at all).
pub fn model_present(models_dir: &Path, model: &teletype_speech::catalog::SpeechModel) -> bool {
    match engine_kind(model) {
        EngineKind::Fluid => fluid_bridge_available(),
        // OS-managed assets: the bridge being linked is what "present" means
        // (the provider installs the locale on first load, bounded by a
        // 10 minute timeout).
        EngineKind::AppleSpeech => apple_bridge_available(),
        EngineKind::Sherpa => {
            let dir = model_path_for(models_dir, model);
            [
                "encoder.int8.onnx",
                "decoder.int8.onnx",
                "joiner.int8.onnx",
                "tokens.txt",
            ]
            .iter()
            .all(|f| dir.join(f).is_file())
        }
        EngineKind::GgmlParakeet
        | EngineKind::GgmlWhisper
        | EngineKind::ParakeetCpp
        | EngineKind::TranscribeCpp => model_path_for(models_dir, model).is_file(),
        // Two GGUFs in one directory; the harness never drives this engine, but
        // presence still has to answer honestly.
        EngineKind::Qwen3Asr => {
            let dir = model_path_for(models_dir, model);
            teletype_speech::catalog::QWEN3_ASR_ARTIFACTS
                .iter()
                .all(|a| dir.join(a.file).is_file())
        }
    }
}

/// The language string to pass to `transcribe` for this engine.
///
/// Parakeet (ggml, Core ML) and sherpa are fixed-language engines: "auto"
/// means English. Whisper can auto-detect, so it keeps "auto".
pub fn asr_language(model: &teletype_speech::catalog::SpeechModel) -> &'static str {
    if engine_kind(model) == EngineKind::GgmlWhisper {
        "auto"
    } else {
        "en"
    }
}

